const result = checkManifests(root, [resolve(root, rel)]);
rememberManifests(repo, [resolve(root, rel)]); // a later shell command does not re-report this state
const lines = formatResult(result);
if (result.violations.length > 0) {
  postToolBlock(
    `Manifest check failed for ${rel}:\n${lines.join('\n')}\n` +
    'Fix the manifest following the owners named above; dependency changes follow the add-dependency workflow.',
  );
}

if (attrs.versionoverride !== undefined) {
  result.notes.push({ file: rel, message: `${id}: VersionOverride "${attrs.versionoverride}" needs a concrete, documented reason` });
}

- When explicit versioning is required, use one strategy consistently;
  URL-segment versioning is the default unless project requirements justify
  another strategy.

- Bearer/OIDC for an SPA calling an API;
- cookies for server-rendered interactive applications;
- ASP.NET Core Identity when the application owns local accounts, passwords, and needs account management — not merely because a business entity is called `User`;
- an external OpenID Connect/OAuth provider when identity is delegated — do not issue custom JWTs when that provider already issues tokens.

const LAYERS = ['Domain', 'Application', 'Infrastructure', 'Api'];
const ALLOWED_PRODUCTION_REFERENCES = {
  Domain: [],
  Application: ['Domain'],
  Infrastructure: ['Application', 'Domain'],
  Api: ['Application', 'Infrastructure', 'Domain'],
};
